        (isSupportedImage(mimeType) ||
            isVideo(mimeType) ||
            isAudio(mimeType) ||
            isSupportedText(mimeType) ||
            (hasPDFSupport() && isPDF(mimeType)) ||
            isWordDocument(mimeType))
